-- Verified 100 ml editions from Lattafa and Afnan. Manufacturer photographs and editorial images only.
-- Comparison prices as published on Oscar Fragrances (Khamrah Dukhan, 23 JOD) and Afnan Jordan (9 PM Rebel, 25 JOD) on 2026-11-27.
-- Remove the two previously supplied packaging photos. Keep all other photos and their order.
UPDATE product_photo_galleries
SET photos_json = (
  SELECT json_group_array(json(item.value))
  FROM json_each(photos_json) AS item
  WHERE json_extract(item.value,'$.url') NOT IN (
    '/media/catalog/TSPF-HER-CONFESSION-02b9415867d8.webp',
    '/media/catalog/TSPF-MUSAMAM-WHITE-INTENSE-4bd665a61bc2.webp'
  )
), revision = revision + 1, change_token = lower(hex(randomblob(16))), updated_at = datetime('now')
WHERE product_id IN ('TSPF-HER-CONFESSION', 'TSPF-MUSAMAM-WHITE-INTENSE')
  AND EXISTS (
    SELECT 1 FROM json_each(photos_json) AS item
    WHERE json_extract(item.value,'$.url') IN (
      '/media/catalog/TSPF-HER-CONFESSION-02b9415867d8.webp',
      '/media/catalog/TSPF-MUSAMAM-WHITE-INTENSE-4bd665a61bc2.webp'
    )
  );
INSERT INTO products (id,brand,name,category,subcategory,description,details_json,reference_price_fils,price_fils,discount_percent,image_url,source_url,source_shop,stock,approved,active) VALUES ('TSPF-ASAD-BOURBON','Lattafa','Asad Bourbon Eau de Parfum 100 ml','العطور','العطور','يبدأ عطرك بلمسة مشرقة من البرقوق والفلفل الوردي. ثم تظهر رائحة الكاكاو مع جوزة الطيب، قبل أن تستقر فانيلا بوربون والعنبر. يناسب الأجواء الباردة إذا كنت تحب دفء الفانيلا ولمسة التوابل.','{"nameAr":"لطافة أسد بوربون · أو دو بارفان للجنسين 100 مل","tagline":"كاكاو وفانيلا لأمسية دافئة","productType":"fragrance","size":"100 مل","collection":"beauty","koreanCare":false,"imageType":"photo","benefits":["المقدمة من الفلفل الوردي والخزامى وبرقوق ميرابيل","القلب من الكاكاو والدافانا وجوزة الطيب","القاعدة من نجيل الهند وفانيلا بوربون والعنبر"],"howToUse":"رُشّ العطر على المعصم أو الرقبة واتركه يجف.","notes":"للاستخدام الخارجي. راجع قائمة المكونات المطبوعة على العبوة إذا كانت لديك حساسية من العطور.","en":{"name":"Asad Bourbon Eau de Parfum 100 ml","tagline":"Cocoa and vanilla for a warm evening","description":"Plum and pink pepper brighten the first spray. Cocoa and nutmeg take over before Bourbon vanilla and amber settle in. A warm choice for cooler evenings.","benefits":["Pink pepper, lavender and Mirabelle plum at the opening","Cocoa, davana and nutmeg in the heart","Vetiver, Bourbon vanilla and amber at the base"],"howToUse":"Spray on your wrists or neck and let it dry.","notes":"For external use. Check the ingredient list on the packaging if you are sensitive to fragrances.","size":"100 ml"}}',6900,6900,0,'/media/catalog/TSPF-ASAD-BOURBON-fb249f5d617c.webp','https://lattafa.com/product/asad-bourbon/','Lattafa',24,1,1) ON CONFLICT(id) DO NOTHING;
