INSERT INTO products (id,brand,name,category,subcategory,description,details_json,reference_price_fils,price_fils,discount_percent,image_url,source_url,source_shop,stock,approved,active) VALUES ('TSPF-ASAD','Lattafa','Asad Eau de Parfum 100 ml','العطور','العطور','يناسب إطلالة مسائية مرتّبة. يلفت الفلفل الأسود الانتباه أولًا مع لمسة أناناس، ثم تظهر القهوة والباتشولي بطابع أعمق. تلطّف الفانيلا والعنبر نهاية الرائحة وتبقى الأخشاب واضحة.','{"nameAr":"لطافة أسد · أو دو بارفان رجالي 100 مل","tagline":"قهوة وتوابل بطابع خشبي","productType":"fragrance","size":"100 مل","collection":"beauty","koreanCare":false,"imageType":"photo","benefits":["المقدمة من الفلفل الأسود والأناناس والتبغ","القلب من القهوة والسوسن والباتشولي","القاعدة من العنبر والفانيلا والأخشاب الجافة والجاوي واللابدانوم"],"howToUse":"رُشّ العطر على المعصم أو الرقبة واتركه يجف.","notes":"للاستخدام الخارجي. راجع قائمة المكونات المطبوعة على العبوة إذا كانت لديك حساسية من العطور.","en":{"name":"Asad Eau de Parfum 100 ml","tagline":"Coffee and spice with a woody finish","description":"A dressed-up evening scent. Black pepper and a hint of pineapple open before coffee and patchouli deepen the scent. Amber, vanilla and dry woods soften the finish.","benefits":["Black pepper, pineapple and tobacco at the opening","Coffee, iris and patchouli in the heart","Amber, vanilla, dry woods, benzoin and labdanum at the base"],"howToUse":"Spray on your wrists or neck and let it dry.","notes":"For external use. Check the ingredient list on the packaging if you are sensitive to fragrances.","size":"100 ml"}}',6000,6000,0,'/media/catalog/TSPF-ASAD-5c3d47786b32.webp','https://lattafa.com/product/asad/','Lattafa',24,1,1) ON CONFLICT(id) DO NOTHING;
