INSERT INTO products (id,brand,name,category,subcategory,description,details_json,reference_price_fils,price_fils,discount_percent,image_url,source_url,source_shop,stock,approved,active) VALUES ('TSPF-YARA-CANDY','Lattafa','Yara Candy Eau de Parfum 100 ml','العطور','العطور','إذا كنت تحبين رائحة فاكهية حلوة وواضحة، يبدأ يارا كاندي بالمندرين والكشمش الأسود، ثم تظهر نفحة حلوى الفراولة مع الغاردينيا. تترك الفانيلا والمسك إحساسًا دافئًا يكمل المشاوير النهارية.','{"nameAr":"لطافة يارا كاندي · أو دو بارفان نسائي 100 مل","tagline":"فراولة وحلاوة مرحة للنهار","productType":"fragrance","size":"100 مل","collection":"beauty","koreanCare":false,"imageType":"photo","benefits":["المقدمة من المندرين الأخضر والكشمش الأسود","القلب من حلوى الفراولة الفوّارة والغاردينيا","القاعدة من خشب الصندل وشراب الفانيلا والمسك والعنبر"],"howToUse":"رُشّ العطر على المعصم أو الرقبة واتركه يجف.","notes":"للاستخدام الخارجي. راجع قائمة المكونات المطبوعة على العبوة إذا كانت لديك حساسية من العطور.","en":{"name":"Yara Candy Eau de Parfum 100 ml","tagline":"Playful strawberry sweetness for daytime","description":"A playful sweet scent for daytime. Green mandarin and blackcurrant give way to fizzy strawberry candy and gardenia, followed by a warm vanilla and musk finish.","benefits":["Green mandarin and blackcurrant at the opening","Strawberry fizz candy and gardenia in the heart","Sandalwood, vanilla syrup, musk and amber at the base"],"howToUse":"Spray on your wrists or neck and let it dry.","notes":"For external use. Check the ingredient list on the packaging if you are sensitive to fragrances.","size":"100 ml"}}',6000,6000,0,'/media/catalog/TSPF-YARA-CANDY-0e52505dcb4d.webp','https://lattafa.com/product/yara-candy/','Lattafa',24,1,1) ON CONFLICT(id) DO NOTHING;
