INSERT INTO products (id,brand,name,category,subcategory,description,details_json,reference_price_fils,price_fils,discount_percent,image_url,source_url,source_shop,stock,approved,active) VALUES ('TSPF-YARA','Lattafa','Yara Eau de Parfum 100 ml','العطور','العطور','رائحة ناعمة تناسب المشاوير اليومية. تظهر لمسة المندرين والأوركيد مع البداية، ثم تأتي حلاوة استوائية بطابع كريمي. يستقر المسك مع الفانيلا وخشب الصندل ليعطي نهاية مريحة ودافئة.','{"nameAr":"لطافة يارا الوردي · أو دو بارفان نسائي 100 مل","tagline":"فانيلا ناعمة ولمسة استوائية","productType":"fragrance","size":"100 مل","collection":"beauty","koreanCare":false,"imageType":"photo","benefits":["المقدمة من المندرين والهيليوتروب والأوركيد","القلب من نفحات استوائية وحلوة","القاعدة من الفانيلا وخشب الصندل والمسك"],"howToUse":"رُشّ العطر على المعصم أو الرقبة واتركه يجف.","notes":"للاستخدام الخارجي. راجع قائمة المكونات المطبوعة على العبوة إذا كانت لديك حساسية من العطور.","en":{"name":"Yara Eau de Parfum 100 ml","tagline":"Soft vanilla with a tropical touch","description":"A soft everyday scent. Tangerine and orchid give way to creamy tropical sweetness, then vanilla, musk and sandalwood settle into a comforting finish.","benefits":["Tangerine, heliotrope and orchid at the opening","Tropical and gourmand notes in the heart","Vanilla, sandalwood and musk at the base"],"howToUse":"Spray on your wrists or neck and let it dry.","notes":"For external use. Check the ingredient list on the packaging if you are sensitive to fragrances.","size":"100 ml"}}',6000,6000,0,'/media/catalog/TSPF-YARA-ff87a6b397c5.webp','https://lattafa.com/product/yara/','Lattafa',24,1,1) ON CONFLICT(id) DO NOTHING;
