INSERT INTO products (id,brand,name,category,subcategory,description,details_json,reference_price_fils,price_fils,discount_percent,image_url,source_url,source_shop,stock,approved,active) VALUES ('TSPF-YARA-MOI','Lattafa','Yara Moi Eau de Parfum 100 ml','العطور','العطور','يبدأ يارا موي بانتعاش الكمثرى مع لمسة فلفل وردي، ثم يفتح الياسمين ومسك الروم قلبًا زهريًا ينعّمه اللوز. يظل الباتشولي خفيفًا بجانب الفانيلا، فيناسب من تحب الأزهار الدافئة.','{"nameAr":"لطافة يارا موي الأبيض · أو دو بارفان نسائي 100 مل","tagline":"أزهار بيضاء مع دفء اللوز","productType":"fragrance","size":"100 مل","collection":"beauty","koreanCare":false,"imageType":"photo","benefits":["المقدمة من الكمثرى والفلفل الوردي والكشمش الأسود","القلب من مسك الروم والياسمين واللوز","القاعدة من الفانيلا والكاشميران والباتشولي"],"howToUse":"رُشّ العطر على المعصم أو الرقبة واتركه يجف.","notes":"للاستخدام الخارجي. راجع قائمة المكونات المطبوعة على العبوة إذا كانت لديك حساسية من العطور.","en":{"name":"Yara Moi Eau de Parfum 100 ml","tagline":"White flowers with the warmth of almond","description":"Pear and pink pepper give Yara Moi a bright start. Jasmine and tuberose soften with almond, and vanilla and patchouli bring warmth to the finish.","benefits":["Pear, pink pepper and blackcurrant at the opening","Tuberose, jasmine and almond in the heart","Vanilla, cashmeran and patchouli at the base"],"howToUse":"Spray on your wrists or neck and let it dry.","notes":"For external use. Check the ingredient list on the packaging if you are sensitive to fragrances.","size":"100 ml"}}',6300,6300,0,'/media/catalog/TSPF-YARA-MOI-a9f28e3c9df0.webp','https://lattafa.com/product/yara-moi/','Lattafa',24,1,1) ON CONFLICT(id) DO NOTHING;
