INSERT INTO products (id,brand,name,category,subcategory,description,details_json,reference_price_fils,price_fils,discount_percent,image_url,source_url,source_shop,stock,approved,active) VALUES ('TSPF-KHAMRAH-DUKHAN','Lattafa','Khamrah Dukhan Eau de Parfum 100 ml','العطور','العطور','رائحة للمساء إذا كنت تفضّل التوابل المدخّنة. يضيء المندرين البداية قبل أن يتضح البخور والباتشولي، ثم يدفأ العطر مع التبغ والعنبر. تضيف التونكا والبرالين حلاوة تخفّف حدّة الدخان.','{"nameAr":"لطافة خمرة دخان · أو دو بارفان للجنسين 100 مل","tagline":"بخور وتوابل مدخّنة لأمسية باردة","productType":"fragrance","size":"100 مل","collection":"beauty","koreanCare":false,"imageType":"photo","benefits":["المقدمة من المندرين والبهار الحلو والتوابل المدخّنة","القلب من اللادن وزهر البرتقال والبخور والباتشولي","القاعدة من التبغ والعنبر والتونكا والجاوي والبرالين"],"howToUse":"رُشّ العطر على المعصم أو الرقبة واتركه يجف.","notes":"للاستخدام الخارجي. راجع قائمة المكونات المطبوعة على العبوة إذا كانت لديك حساسية من العطور. سعر الدفعة الأولى 6.90 د.أ، أقل بـ70% من سعر 23 د.أ المعروض لدى أوسكار للعطور في الأردن في 27 نوفمبر 2026.","en":{"name":"Khamrah Dukhan Eau de Parfum 100 ml","tagline":"Incense and smoky spice for a cool evening","description":"A warm evening choice if you like smoky spice. Mandarin lifts the opening before incense and patchouli come through. Tobacco and amber deepen the finish, softened by tonka and praline.","benefits":["Mandarin, pimento and smoked spices at the opening","Cistus, orange blossom, incense and patchouli in the heart","Tobacco, amber, tonka, benzoin and praline at the base"],"howToUse":"Spray on your wrists or neck and let it dry.","notes":"For external use. Check the ingredient list on the packaging if you are sensitive to fragrances. This first batch is priced at 6.90 JOD, 70% below the 23 JOD price listed by Oscar Fragrances in Jordan on 27 November 2026.","size":"100 ml"}}',6900,6900,0,'/media/catalog/TSPF-KHAMRAH-DUKHAN-86ed5896ef12.webp','https://lattafa.com/product/khamrah-dukhan/','Lattafa',24,1,1) ON CONFLICT(id) DO NOTHING;
