INSERT INTO products (id,brand,name,category,subcategory,description,details_json,reference_price_fils,price_fils,discount_percent,image_url,source_url,source_shop,stock,approved,active) VALUES ('TSPF-9PM-REBEL','Afnan','9 PM Rebel Eau de Parfum 100 ml','العطور','العطور','انتعاش فاكهي يليق بطلعة مسائية عفوية. يظهر الأناناس والتفاح الأخضر مع أول رشّة، ثم يهدأ العطر مع الأرز وطحلب البلوط. تضيف الفانيلا والكراميل لمسة حلوة في النهاية.','{"nameAr":"أفنان 9 PM ريبِل · أو دو بارفان للجنسين 100 مل","tagline":"تفاح وأناناس بقاعدة خشبية ناعمة","productType":"fragrance","size":"100 مل","collection":"beauty","koreanCare":false,"imageType":"photo","benefits":["المقدمة من المندرين والأناناس والتفاح الأخضر","القلب من خشب الأرز وطحلب البلوط والفانيلا","القاعدة من الكراميل والأخشاب الجافة والعنبر البحري والمسك"],"howToUse":"رُشّ العطر على المعصم أو الرقبة واتركه يجف.","notes":"للاستخدام الخارجي. راجع قائمة المكونات المطبوعة على العبوة إذا كانت لديك حساسية من العطور. سعر الدفعة الأولى 7.50 د.أ، أقل بـ70% من سعر 25 د.أ المعروض لدى أفنان الأردن في 27 نوفمبر 2026.","en":{"name":"9 PM Rebel Eau de Parfum 100 ml","tagline":"Apple and pineapple over soft woods","description":"A bright fruity scent for an easy evening out. Pineapple and green apple start things off, then cedar and oakmoss soften the fruit. Vanilla and caramel add gentle sweetness.","benefits":["Mandarin, pineapple and Granny Smith apple at the opening","Cedarwood, oakmoss and vanilla in the heart","Caramel, dry woods, ambergris and musk at the base"],"howToUse":"Spray on your wrists or neck and let it dry.","notes":"For external use. Check the ingredient list on the packaging if you are sensitive to fragrances. This first batch is priced at 7.50 JOD, 70% below the 25 JOD price listed by Afnan Jordan on 27 November 2026.","size":"100 ml"}}',7500,7500,0,'/media/catalog/TSPF-9PM-REBEL-0f635e3001f6.webp','https://jordan.afnan.com/products/9-pm-rebel','Afnan',24,1,1) ON CONFLICT(id) DO NOTHING;
